{
  "headline": "FDA's records trace our supply to a plant classified OAI 145 days before the shortage posting",
  "headline_cites": ["D9"],
  "sentences": [
    {
      "text": "Vecuronium bromide is not on FDA's current shortage list as of 2026-10-21; FDA's history shows an earlier shortage first posted on 2020-05-06, since resolved.",
      "cites": ["D11"]
    },
    {
      "text": "FDA inspection 1112832 at Sun Pharmaceutical Industries Ltd. ended 2019-12-13 and was classified OAI with 8 observations on the Form 483.",
      "cites": ["E13"]
    },
    {
      "text": "That OAI classification occurred 145 days before FDA posted the shortage on 2020-05-06.",
      "cites": ["D9"]
    },
    {
      "text": "FDA inspection 1041554 at Eugia Pharma Specialities Limited ended 2018-02-20 and was classified VAI, 806 days before the 2020-05-06 posting.",
      "cites": ["D5"]
    },
    {
      "text": "FDA inspection 1090548 at Gland Pharma Limited ended 2019-05-16 and was classified VAI, 356 days before the 2020-05-06 posting.",
      "cites": ["D8"]
    },
    {
      "text": "The top-ranked option by rule is to buy from Mylan Institutional LLC, which is not on FDA's shortage list today and uses plant MYLAN LABS LTD.",
      "cites": ["D12"]
    },
    {
      "text": "An approved P&T interchange exists for the same product from Gland Pharma Limited (NDC 68083013910), approved by Jordan Hale, PharmD on 2026-01-27.",
      "cites": ["D13", "E42"]
    }
  ]
}
